async function prepare(request,button=actionButton){
 if(walletMode())return spendCoins(request,button);
 clearInlineOrder();const serial=++prepareSerial,label=button?.textContent;
 if(button){let reason=writeRestriction(state);try{if(!reason)quoteRule(state.world,state.user.id,request);}catch(e){reason=e.message;}if(reason){setButtonRequirement(button,reason);showActionRequirement(button);return;}button.dataset.orderBusy='1';button.disabled=true;button.textContent='A preparar…';}
 try{
  const q=await api('/api/plan',request);if(serial!==prepareSerial||!button?.isConnected)return;if(writeRestriction(state)){delete button.dataset.orderBusy;button.disabled=false;button.textContent=label;setButtonRequirement(button,writeRestriction(state));showActionRequirement(button);return;}
  if(request.action==='equipar'){equipmentDraft=markEquipmentPending(equipmentDraft,q.code);const status=$('.equipment-editor>span');if(status){status.className='equipment-pending';status.textContent='◷ Aguardar confirmação na Twitch';status.setAttribute('role','status');}}planRequest=request;$('#plan').innerHTML='';document.body.classList.remove('order-open');
  if(request.kind==='navegar'&&q.payload?.route){previewVoyage={route:q.payload.route,createdAt:clock(),existingIds:state.world.missions.map(m=>m.id),target:q.payload.target};updateRoutes();}
  const reward={construcoes:'Construções',navegar:'Navegar',aliancas:'Alianças',gestao:'Gestão'}[q.kind]||'Entrar';
  const hint=document.createElement('small');hint.className='inline-order-hint';hint.textContent=q.cost+' pontos'+(q.seconds>0?' · '+time(q.seconds):'')+' · '+(config.demo?'Teste local':'Colar em Grand Line · '+reward);button.after(hint);
  delete button.dataset.orderBusy;setButtonRequirement(button,'');button.classList.add('copy-ready');button.disabled=false;
  if(config.demo){button.dataset.inlineExecute='1';button.textContent='Executar no teste';}else{button.dataset.inlineCode=q.code;button.textContent='Copiar código → '+reward;}
  inlineOrder={button,label,hint,q,request,timer:setTimeout(()=>{clearInlineOrder();toast('Código expirado. Prepara novamente a ação.');},600000)};decorateGuide();
 }catch(e){if(button?.isConnected){delete button.dataset.orderBusy;button.disabled=false;button.textContent=label;setButtonRequirement(button,e.message);showActionRequirement(button);}else toast(e.message);}
}
