 if(b.dataset.equipSet||b.dataset.equip||b.dataset.unequip||b.dataset.equipmentReset){const p=me();clearInlineOrder();planRequest=null;equipmentDraft=reconcileEquipmentDraft(equipmentDraft,p,state.order);equipmentDraft=selectEquipment(equipmentDraft,p,{item:b.dataset.equip,slot:b.dataset.unequip,set:b.dataset.equipSet,reset:!!b.dataset.equipmentReset});inspectInventory();return;}
