function inspectSea(id){const w=state.world,b=w.bots.find(b=>b.id===id),r=(w.wrecks||[]).find(r=>r.id===id);selected={id};document.body.classList.add('inspector-open');if(!b&&!r){$('#detail').innerHTML='<h2>O alvo já saiu</h2>';return;}const mine=me(),e=w.encounters[id],access=b?npcAccess(mine,b):{ok:true},flag=b?npcFlag(b):npcFlag(r);let html=`<div class="target-identity">${flagSVG(flag)}<span class="pill">${b?npcProfile(b).label+' · NPC':'DESTROÇOS'}</span></div><h2>${esc(b?.name||r.name)}</h2>${b?accessBadge(mine,b):'<div class="attack-access '+(r.lockedBy?'neutral':'')+'">'+(r.lockedBy?'◷ Recolha em curso':'✓ Loot livre · qualquer nível')+'</div>'}${stats([['Sai do mapa em',countdown(b?.end||r.end)],...(b?[['Tripulação',b.troops],['Loot de rota',b.lootBonus>1.02?'+'+Math.round((b.lootBonus-1)*100)+'%':'Normal']]:[])])}<div class="wreck-loot">${Object.entries(b?.loot||r.resources).map(([k,n])=>`<span>${icon(k)}${num(n)}</span>`).join('')}</div>${b?'<div class="target-fleet">'+Object.entries(b.fleet||{}).filter(([,n])=>n).map(([k,n])=>'<span><img src="assets/fleet-'+k+'.png" alt="'+SHIPS[k]+'">×'+n+'</span>').join('')+'</div>':''}${e?'<button class="primary wide" data-battle="'+e.id+'">⚔ Ver batalha em direto</button>':''}`;
if(state.needsDevice)html+=deviceGate();else if(!mine)html+='<button data-action="found">Criar a minha ilha</button>';else if(!access.ok)html+='<p class="level-range">Precisas de N'+access.min+'–'+access.max+'</p>';else if(r?.lockedBy)html+='<p>Disponível depois da recolha atual.</p>';else{if(b)html+=partyStatus(w,b.id,'ataque');const ship=b&&mine.fleet.combate?'combate':mine.fleet.cargueiro?'cargueiro':mine.fleet.combate?'combate':Object.keys(SHIPS).find(k=>mine.fleet[k]>0),available=mine.troops-defendingTroops(mine);html+=`<h3>Frota</h3><div class="fields">${Object.entries(SHIPS).map(([k,name])=>`<label class="fleet-input">${name} (${mine.fleet[k]})<input id="send-${k}" type="number" min="0" max="${mine.fleet[k]}" value="${k===ship?1:0}"></label>`).join('')}<label>Marinheiros<input id="send-troops" type="number" min="0" max="${available}" value="${r?0:Math.min(20,available)}"></label></div><button class="primary wide" data-action="sail" ${!ship||b&&available<=0?'disabled':''}>${r?'Preparar recolha':'Preparar ataque'} · 200 moedas</button>`;}$('#detail').innerHTML=html;updateSailingCrew();simplifyCurrentView();updateRoutes();}



