function actionRequest(button){
 const d=button.dataset,p=me(),n=(selector,fallback=0)=>Number($(selector)?.value??fallback);
 if(d.action==='confirm-equipment')return equipmentDraftOrder(equipmentDraft||createEquipmentDraft(p));
 if(d.action==='expand-inventory'){const e=inventoryExpansion(p);return{kind:'gestao',action:'ampliar-inventario',payload:{tier:e.tier,payment:e.paid}};}
 if(d.dismantle)return{kind:'gestao',action:'desmontar',payload:{items:[...inventorySelection]}};
 if(d.upgrade)return{kind:'construcoes',action:'edificio',payload:{building:d.upgrade}};
 if(d.recruit)return{kind:'construcoes',action:d.recruit,payload:{count:Number(button.closest('[data-recruit-option]').querySelector('input')?.value||1)}};
 if(d.ship)return{kind:'construcoes',action:'navios',payload:{ship:d.ship,count:Number(button.closest('[data-ship-option]').querySelector('input')?.value||1)}};
 if(d.tech)return{kind:'construcoes',action:'pesquisa',payload:{tech:d.tech}};
 if(d.repair)return{kind:'construcoes',action:'reparar',payload:{building:d.repair}};
 if(d.alliance)return{kind:'aliancas',action:'entrar',payload:{alliance:d.alliance,invite:$('#invite-'+d.alliance)?.value?.trim()||''}};
 if(d.action==='work'){const el=button.closest('[data-workers-panel]');return{kind:'gestao',action:'trabalhar',payload:{woodWorkers:Number(el.querySelector('[data-workers-resource=wood]').value),stoneWorkers:Number(el.querySelector('[data-workers-resource=stone]').value)}};}
 if(d.action==='fish')return{kind:'gestao',action:'pescar'};
 if(d.action==='garrison')return{kind:'gestao',action:'guarnicao',payload:{count:n('#garrison')}};
 if(d.action==='resume')return{kind:'gestao',action:'regressar'};
 if(d.action==='link-device')return{kind:'gestao',action:'ligar'};
 if(d.action==='repair')return{kind:'construcoes',action:'reparar'};
 if(d.action==='train')return{kind:'construcoes',action:'tropas',payload:{count:n('#train-count')}};
 if(d.action==='create-alliance')return{kind:'aliancas',action:'criar',payload:{name:$('#alliance-name')?.value||''}};
 if(d.action==='leave-alliance')return{kind:'aliancas',action:'sair'};
 if(d.action==='confirm-flag'&&p)return{kind:'gestao',action:'bandeira',payload:{flag:readFlagEditor()}};
 if(d.action==='sail')return{kind:'navegar',action:'enviar',payload:{target:selected?.id,fleet:Object.fromEntries(Object.keys(SHIPS).map(k=>[k,n('#send-'+k)])),troops:n('#send-troops'),...($('#send-side')?{side:$('#send-side').value}:{})}};
 return null;
}
function refreshActionRequirements(){
 if(!state)return;if(!me()){for(const b of document.querySelectorAll('[data-action=found],[data-action=confirm-flag]'))setButtonRequirement(b,writeRestriction(state)||walletRequirement({kind:'entrar'}));return;}
 for(const button of document.querySelectorAll('#view button,#detail button')){
  if(button.dataset.orderBusy||button.dataset.inlineCode||button.dataset.inlineExecute)continue;
  try{const request=actionRequest(button);if(!request)continue;let reason=writeRestriction(state);try{if(!reason)quoteRule(state.world,state.user.id,request);if(!reason)reason=walletRequirement(request);}catch(e){reason=e.message;}setButtonRequirement(button,reason);}catch(e){setButtonRequirement(button,e.message);}
 }
}
document.addEventListener('click',e=>{if(e.target.closest('button')?.dataset.requirement){refreshActionRequirements();interceptRequirement(e,showActionRequirement);}},true);
document.addEventListener('input',()=>refreshActionRequirements());
document.addEventListener('change',()=>refreshActionRequirements());

function showActionRequirement(button){requirementFeedbackUntil=Date.now()+1200;highlightRequirement(button);decorateGuide();}

function openAdventurePanel(id,html){if(selected?.id!==id){clearInlineOrder();planRequest=null;$('#plan').innerHTML='';previewVoyage=null;}selected={id};document.body.classList.add('inspector-open');$('#detail').innerHTML=html;refreshActionRequirements();decorateGuide();}
function inspectItem(key){
 const p=me(),split=key.indexOf(':'),kind=key.slice(0,split),id=key.slice(split+1),record=kind==='secret'?state.world.finalDiscoveries?.[id]:null;
 const item=kind==='type'?{type:id}:kind==='owned'?p?.inventory.find(i=>i.id===id)||(p?.pendingUniqueItem?.id===id?p.pendingUniqueItem:null):record?.equipment;
 if(!item&&!record){toast('Item indisponível.');return;}
 if(!selected?.id?.startsWith('item:')){itemReturnTarget=selected?.id||'inventory';itemReturnState=capturePanelState($('.inspector'));}
 openAdventurePanel('item:'+key,item?itemDetailsView(item,p,{catalog:kind==='type'}):discoveryDetailsView(record));
}
function inspectInventory(){const p=me();if(!p)return;equipmentDraft=reconcileEquipmentDraft(equipmentDraft,p,state.order);for(const id of inventorySelection)if(!p.inventory?.some(i=>i.id===id))inventorySelection.delete(id);openAdventurePanel('inventory',inventoryView(p,inventorySelection,{draft:equipmentDraft}));}
function inspectReports(){const p=me();if(!p)return;openAdventurePanel('reports',reportView(state.world,p,adventureReadiness(state.world,p,quoteRule),clock()));writePref('grand-line-reports-'+p.id+'-'+(state.world.previewInstance||'live'),String(p.reportSerial||0));updateAdventureTools();}
function updateAdventureTools(){let el=$('#adventure-tools');if(!el){el=document.createElement('div');el.id='adventure-tools';el.className='adventure-tools';$('.header-tools').prepend(el);}const p=me();el.hidden=!p;if(!p)return;const seen=Number(adventurePref('grand-line-reports-'+p.id+'-'+(state.world.previewInstance||'live'))),unread=(p.reports||[]).filter(r=>r.id>seen).length,ready=adventureReadiness(state.world,p,quoteRule);el.innerHTML='<button data-adventure="inventory" title="Inventário e equipamento" aria-label="Inventário">'+icon('treasure')+'<span class="tool-label">Inventário</span><b>'+(p.inventory?.length||0)+'/'+inventoryCapacity(p)+'</b></button><button data-adventure="reports" title="Relatórios e oportunidades" aria-label="Relatórios">🔔<span class="tool-label">Relatórios</span>'+(unread?'<b class="unread-count">'+unread+'</b>':ready.length?'<b class="ready-dot" title="Ações disponíveis">'+ready.length+'</b>':'')+'</button>';}
function inspectBoss(id){const w=state.world,b=w.bosses?.find(b=>b.id===id);if(!b)return;const p=me(),a=bossAccess(w,p,b),e=w.encounters[id],d=DROP_TABLES[b.grade];let html='<span class="pill">ILHA HOSTIL · N'+b.level+'</span><h2>'+esc(b.name)+'</h2>'+bossPortrait(b)+'<h3>'+esc(b.bossName)+'</h3><div class="attack-access '+(a.ok?'':'blocked')+'">'+(a.ok?'⚔ ':'◷ ')+esc(a.label)+'</div>';
if(!bossAlive(w,b))html+='<div class="boss-respawn">Regressa em '+countdown(b.respawnAt)+'</div>';else html+=bossLootView(b,w,p);
if(e)html+='<button class="primary wide" data-battle="'+e.id+'">⚔ Ver combate</button>';
if(p&&a.ok&&e?.phase!=='loot'){html+=partyStatus(w,b.id,'ataque');const ship=p.fleet.combate?'combate':p.fleet.cargueiro?'cargueiro':'pesqueiro',available=p.troops-defendingTroops(p);html+='<h3>Enviar frota</h3><div class="fields">'+Object.entries(SHIPS).map(([k,name])=>'<label class="fleet-input">'+name+' ('+p.fleet[k]+')<input id="send-'+k+'" type="number" min="0" max="'+p.fleet[k]+'" value="'+(k===ship?Math.min(b.final?2:1,p.fleet[k]):0)+'"></label>').join('')+'<label>Marinheiros<input id="send-troops" type="number" min="0" max="'+available+'" value="'+Math.min(b.final?80:40,available)+'"></label></div><button class="primary wide" data-action="sail">Preparar ataque · 200 moedas</button>';}
openAdventurePanel(id,html);updateSailingCrew();updateRoutes();}
function queueRewardReveals(){const p=me();if(!p)return;const key='grand-line-loot-'+p.id+'-'+(state.world.previewInstance||'live'),last=Number(adventurePref(key)),fresh=(p.reports||[]).filter(r=>r.type==='recompensa'&&r.id>last);if(!fresh.length)return;writePref(key,String(fresh.at(-1).id));for(const r of fresh.slice(-5))if(!rewardQueue.some(v=>v.id===r.id))rewardQueue.push(r);showNextReward();}
function showNextReward(){if(rewardShowing||!rewardQueue.length)return;rewardShowing=true;const r=rewardQueue.shift(),el=document.createElement('div');el.id='reward-reveal';el.className='reward-reveal';el.innerHTML=rewardDialog(r);document.body.append(el);el.querySelector('button').focus();}
function closeRewardReveal(){$('#reward-reveal')?.remove();rewardShowing=false;showNextReward();}
document.addEventListener('change',e=>{const id=e.target.dataset?.salvageItem;if(!id)return;if(e.target.checked){if(inventorySelection.size>=10){e.target.checked=false;toast('Até 10 itens por ordem.');return;}inventorySelection.add(id);}else inventorySelection.delete(id);const snapshot=captureGameUI();clearInlineOrder();inspectInventory();restoreGameUI(snapshot);});

function adventurePref(key){try{return localStorage.getItem(key)||'0';}catch{return'0';}}

function guideWaitingBadge(key){if(guidePaused)return'';const step=learningState().current,wait=step?.waiting;if(wait?.kind!=='resources'||wait.building!==key)return'';return '<div class="guide-wait" data-guide-wait><span>'+esc(wait.needsNewShift?'Próximo turno':'Recursos para o próximo passo')+'</span>'+(Number.isFinite(wait.end)?countdown(wait.end):'')+'</div>';}
function captureGameUI(){return{context:tab+'|'+(selected?.id||''),view:capturePanelState($('#view')),inspector:capturePanelState($('.inspector'))};}
function restoreGameUI(snapshot){if(!snapshot||snapshot.context!==tab+'|'+(selected?.id||''))return;restorePanelState($('#view'),snapshot.view);restorePanelState($('.inspector'),snapshot.inspector);updateRecruitmentPreview();updateWorkersPreview();updateSailingCrew();refreshActionRequirements();decorateGuide();}

function partyStatus(w,targetId,side){const summary=combatSummary(w,targetId),ids=summary[side==='defesa'?'defense':'attack'],members=ids.map(user=>({user,types:w.missions.find(m=>m.user===user&&m.target===targetId&&m.phase!=='regresso')?.gearTypes||w.encounters[targetId]?.homeGearTypes||[]})),combo=partySynergy(members);return '<div id="combat-party-status" class="party-status"><span>'+ids.length+'/3 capitães</span>'+(combo.bonus?'<b>Combinação +'+combo.bonus+'%</b>':'')+'</div>';}
function combatChoice(w,p,target){const choice=participation(w,p,target.id);return '<div class="combat-choice">'+(choice.automatic?'<input type="hidden" id="send-side" value="'+choice.role+'"><strong>'+(choice.role==='defesa'?'⛨ Defender aliado':'⚔ Atacar com aliados')+'</strong>':'<label>Lado<select id="send-side"><option value="ataque">⚔ Atacar</option><option value="defesa">⛨ Defender</option></select></label>')+partyStatus(w,target.id,choice.role)+'</div>';}

window.addEventListener('grand-line:auth-changed',()=>{clearInlineOrder();state=null;selected=null;equipmentDraft=null;awaitingLogin=false;clearPrivateUI();refresh();});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&awaitingLogin){awaitingLogin=false;refresh();}});

function updateConsultationNotice(){const node=$('#notice');if(!node||!state)return;if(config.ownerPreview||config.demo){node.hidden=true;return;}if(writeRestriction(state)){node.hidden=false;const at=state.snapshotAt||state.publishedAt;node.textContent=state.consultationSource&&state.consultationSource!=='server'?'Só consulta · sincronizado em '+new Date(at).toLocaleString('pt-PT',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):'Só consulta · servidor desligado';}else if(config.github&&!config.launchEnabled){node.hidden=false;node.textContent='Partida ainda não aberta';}else node.hidden=true;}

function clearPrivateUI(){document.body.classList.remove('purchase-feedback-open');$('#purchase-status').hidden=true;$('#purchase-inline').hidden=true;for(const selector of ['#wallet-button','#adventure-tools'])$(selector)?.remove();for(const selector of ['#resources','#view','#detail','#plan','#captain-identity']){const node=$(selector);if(node)node.innerHTML='';}document.body.classList.remove('inspector-open','order-open');}
function updateWalletButton(){if(!state)return;let b=$('#wallet-button');if(!b){b=document.createElement('button');b.id='wallet-button';b.dataset.walletOpen='1';b.className='wallet-button';$('.header-tools').prepend(b);}b.title='Carteira · '+num(walletBalance())+' moedas';b.setAttribute('aria-label','Carteira');b.innerHTML=coinIcon()+'<b>'+num(walletBalance())+'</b><span>＋</span>';}
async function inspectWallet(){const id='wallet';selected={id};if($('#inspector-title'))$('#inspector-title').textContent='Carteira';document.body.classList.add('inspector-open');const data=await api('/api/wallet');if(selected?.id!==id)return;$('#detail').innerHTML=walletView(data,{demo:config.demo||config.ownerPreview,readOnly:!!writeRestriction(state)||data.offline,canLoad:fundingOpen(state),pack:config.coinPack||500});}
function showPurchase(info){document.body.classList.add('purchase-feedback-open');for(const el of [$('#purchase-status'),$('#purchase-inline')]){if(!el)continue;el.hidden=false;el.dataset.state=info.state;el.innerHTML='<span class="purchase-symbol" aria-hidden="true">'+({confirmed:'✓',rejected:'!',pending:'◷',sending:'◷'}[info.state]||'◷')+'</span><div><strong>'+esc(info.title)+'</strong>'+(info.detail?'<small>'+esc(info.detail)+'</small>':'')+'</div>'+(info.state==='pending'?'<button data-wallet-open="1">Ver compra</button>':'<button data-purchase-dismiss="1" aria-label="Fechar confirmação">×</button>');}}
function applyPurchaseWallet(result){if(!result.wallet||!state)return;if((state.world.wallet?.revision||0)<=result.wallet.revision)state.world.wallet=result.wallet;updateWalletButton();}
function showReceipt(result){if(result.id)handledOrderKey=result.id+':'+result.status;applyPurchaseWallet(result);showPurchase(purchaseFeedback(result));}
async function spendCoins(request,button=actionButton){
 clearInlineOrder();if(button?.dataset.orderBusy||button?.disabled)return;const actor=state?.user.id,label=button?.textContent;let reason=writeRestriction(state),pending=false,confirmed=false;
 try{if(!reason)quoteRule(state.world,state.user.id,request);if(!reason)reason=walletRequirement(request);}catch(e){reason=e.message;}
 if(reason){showPurchase(purchaseFeedback({orderState:'not_sent',error:reason}));if(button){setButtonRequirement(button,reason);showActionRequirement(button);}return;}
 if(button){button.dataset.orderBusy='1';button.disabled=true;button.textContent='A confirmar…';}
 showPurchase({state:'sending',title:'A confirmar compra…',detail:''});
 try{
  const result=await api('/api/order',{id:crypto.randomUUID(),request});if(state?.user.id!==actor)return;showReceipt(result);
  if(result.status!=='fulfilled'){if(button?.isConnected){button.textContent=label;setButtonRequirement(button,result.error||'Ação não efetuada.');showActionRequirement(button);}return;}
  confirmed=true;if(button?.isConnected){button.textContent='✓ −'+result.cost+' moedas';button.classList.add('purchase-confirmed');}
  if(request.action==='equipar')equipmentDraft=markEquipmentPending(equipmentDraft,result.id);
  if(request.kind==='entrar'){flagDraft=null;selected=null;tab='ilha';document.body.classList.remove('inspector-open');}
  previewVoyage=null;planRequest=null;$('#plan').innerHTML='';void refresh({quiet:true});
 }catch(e){if(state?.user.id!==actor)return;pending=!!e.purchasePending;showPurchase(purchaseFeedback(pending?null:{orderState:'not_sent',error:e.message}));if(button?.isConnected){button.textContent=pending?'A confirmar…':label;if(!pending){setButtonRequirement(button,e.message);showActionRequirement(button);}}}
 finally{if(button?.isConnected&&!pending){delete button.dataset.orderBusy;button.disabled=confirmed;}}
}
